children.$onVisibleAction:
state.task_opt_in_accept ? null : {
        "type": "log_event",
        "handler": "client",
        "payload": {
          "event_name": "chatgpt_suggested_automation_lifecycle",
          "statsig_event_name": "chatgpt_suggested_automation_lifecycle",
          "event_data": {
            "lifecycle_event_name": "shown",
            "conversation_id": state.conversation_id,
            "suggested_automation_instance_id": state.conversation_id != null ? "conversation:" + state.conversation_id : null,
            "origin_surface": state.origin_surface,
            "pill_ui_variant": "refreshed"
          }
        }
      }

children.$onClickAction:
state.task_opt_in_accept ? {
          "patchState": set("submitted", true),
          "cause": "system",
          "handler": "server",
          "type": "task_opt_in_accept",
          "payload": {
            "elicitation_metadata": {
              "elicitation_type": "automation_schedule",
              "stage": "interacted",
              "action": "accept"
            }
          },
          "loadingBehavior": "none"
        } : {
          "patchState": set("submitted", true),
          "handler": "client",
          "type": "issue_new_turn",
          "loadingBehavior": "none",
          "payload": {
            "query": state.creation_guidelines,
            "message_metadata": {
              "is_visually_hidden_from_conversation": true,
              "suggestion_type": "reply",
              "suggested_automation_lifecycle": true,
              "suggested_automation_origin_surface": state.origin_surface,
              "suggested_automation_pill_ui_variant": "refreshed"
            },
            "event_name": "chatgpt_widget_action",
            "statsig_event_name": "suggest_automation_widget_clicked",
            "event_data": {
              "elicitation_metadata": {
                "elicitation_type": "automation_schedule",
                "stage": "interacted",
                "action": "accept"
              },
              "widget_affordance": "OPTION",
              "widget_action_target": "automation_suggestion",
              "widget_action_value": state.label,
              "surface_location": "RESPONSE",
              "content_reference_type": "suggest_automation"
            }
          }
        }

